import { test, expect } from '@playwright/test';

test.describe('Responsive Data Tables', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display data tables stacked vertically on small screens', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 812 }); // Simulate small screen
    const table1 = await page.getByRole('table', { name: 'Data Table 1' });
    const table2 = await page.getByRole('table', { name: 'Data Table 2' });

    expect(await table1.evaluate(node => node.getBoundingClientRect().top)).toBeLessThan(await table2.evaluate(node => node.getBoundingClientRect().top));
  });

  test('should maintain horizontal layout on larger screens', async ({ page }) => {
    await page.setViewportSize({ width: 1024, height: 768 }); // Simulate larger screen
    const table1 = await page.getByRole('table', { name: 'Data Table 1' });
    const table2 = await page.getByRole('table', { name: 'Data Table 2' });

    expect(await table1.evaluate(node => node.getBoundingClientRect().top)).toBeGreaterThan(await table2.evaluate(node => node.getBoundingClientRect().top));
  });
});
